mapper.insert:
/*
    SQL ID : RubricDAO.rubricRegist
    설명 : 루브릭 등록
*/
INSERT INTO
    TB_LMS_RUBRIC
        ( RUBRIC_ID
        , ORG_ID
        , USER_ID
        , RUBRIC_TTL
        , RUBRIC_QSTN_CNT
        , RUBRIC_TYCD
        , UP_RUBRIC_ID
        , USEYN
        , RGTR_ID
        , REG_DTTM )
VALUES
        ( #{rubricId}
        , #{orgId}
        , #{userId}
        , #{rubricTtl}
        , #{rubricQstnCnt}
        , #{rubricTycd}
        , #{upRubricId}
        , 'Y'
        , #{rgtrId}
        , FN_DTTM() )

/*
    SQL ID : RubricDAO.rubricQstnRegist
    설명 : 루브릭 문항 등록
*/
INSERT INTO
    TB_LMS_RUBRIC_QSTN
        ( RUBRIC_QSTN_ID
        , RUBRIC_ID
        , RUBRIC_QSTN_TTL
        , RUBRIC_QSTN_SEQNO
        , EVLRT
        , RUBRIC_EVL_TYCD
        , RGTR_ID
        , REG_DTTM

        , MDFR_ID
        , MOD_DTTM

        )
VALUES
        ( #{rubricQstnId}
        , #{rubricId}
        , #{rubricQstnTtl}
        , #{rubricQstnSeqno}
        , #{evlrt}
        , #{rubricEvlTycd}
        , #{rgtrId}
        , FN_DTTM()

        , #{mdfrId}
        , FN_DTTM()

        )

/*
    SQL ID : RubricDAO.rubricVwitmRegist
    설명 : 루브릭 보기항목 등록
*/
INSERT INTO
    TB_LMS_RUBRIC_VWITM
        ( RUBRIC_VWITM_ID
        , RUBRIC_QSTN_ID
        , RUBRIC_VWITM_TTL
        , RUBRIC_VWITM_PNT
        , RUBRIC_VWITM_SEQNO
        , RGTR_ID
        , REG_DTTM

        , MDFR_ID
        , MOD_DTTM

        )
VALUES
        ( #{rubricVwitmId}
        , #{rubricQstnId}
        , #{rubricVwitmTtl}
        , #{rubricVwitmPnt}
        , #{rubricVwitmSeqno}
        , #{rgtrId}
        , FN_DTTM()

        , #{mdfrId}
        , FN_DTTM()

)

mapper.update:
/*
    SQL ID : RubricDAO.rubricModify
    설명 : 루브릭 수정
*/
UPDATE
    TB_LMS_RUBRIC
SET
    RUBRIC_TTL          = #{rubricTtl}
    , RUBRIC_QSTN_CNT   = #{rubricQstnCnt}
    , MDFR_ID           = #{mdfrId}
    , MOD_DTTM          = FN_DTTM()
WHERE
    RUBRIC_ID = #{rubricId}

/*
    SQL ID : RubricDAO.rubricUseynModify
    설명 : 루브릭 사용여부 수정
*/
UPDATE
    TB_LMS_RUBRIC
SET
    USEYN       =   #{useyn}
    , MDFR_ID   =   #{mdfrId}
    , MOD_DTTM  =   FN_DTTM()
WHERE
    RUBRIC_ID = #{rubricId}

/*
    SQL ID : RubricDAO.upRubricIdModify
    설명 : 상위 루브릭ID 수정
*/
UPDATE
    TB_LMS_RUBRIC
SET
    UP_RUBRIC_ID = #{upRubricId}
WHERE
    RUBRIC_ID = #{rubricId}
